def calcular_inss(salario: float) -> float:
    """Calcula INSS com faixas simplificadas."""
    if salario <= 2000:
        return round(salario * 0.075, 2)
    if salario <= 4000:
        return round(salario * 0.09, 2)
    return round(salario * 0.12, 2)


def calcular_irrf(base: float) -> float:
    """Calcula IRRF com base líquida após INSS."""
    if base <= 2000:
        return 0.0
    if base <= 5000:
        return round(base * 0.1, 2)
    return round(base * 0.15, 2)


def calcular_liquido(salario: float) -> float:
    """Calcula o salário líquido após INSS e IRRF."""
    inss = calcular_inss(salario)
    base_irrf = salario - inss
    irrf = calcular_irrf(base_irrf)
    return round(salario - inss - irrf, 2)

